[
  {
    "question": "In the context of dynamic arrays (e.g., C++ vector or Java ArrayList), which statement correctly describes the amortized time complexity of the `push_back` (or `add`) operation when the array needs to resize?",
    "options": {
      "A": "O(1) amortized, because occasional costly reallocations are spread over many insertions",
      "B": "O(n) amortized, since each insertion may trigger a full copy of the array",
      "C": "O(log n) amortized, due to binary search performed during resizing",
      "D": "O(n log n) amortized, because resizing involves sorting the elements"
    },
    "correct_answer": "A",
    "explanation": "When a dynamic array runs out of capacity it typically allocates a new block of roughly double size and copies the existing elements. The expensive O(n) copy happens only occasionally, so the average (amortized) cost per insertion is constant, O(1).",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following best explains why a hash table with chaining is preferred over open addressing when the load factor may exceed 0.7?",
    "options": {
      "A": "Chaining maintains O(1) worst‑case lookup regardless of load factor",
      "B": "Chaining allows the table to grow without rehashing all elements",
      "C": "Chaining handles collisions by storing multiple keys in the same bucket, keeping average‑case performance stable even at high load factors",
      "D": "Chaining eliminates the need for a hash function"
    },
    "correct_answer": "C",
    "explanation": "In chaining, each bucket holds a linked list (or another structure) of colliding keys. Even if many keys map to the same bucket, the average length of each list grows slowly, so lookup remains close to O(1) when the load factor is moderate to high. Open addressing’s performance degrades sharply after the load factor passes about 0.7.",
    "difficulty": "Medium"
  },
  {
    "question": "Consider a graph with 10,000 vertices and 20,000 edges. Which representation would typically use less memory?",
    "options": {
      "A": "Adjacency matrix",
      "B": "Adjacency list",
      "C": "Incidence matrix",
      "D": "Edge list stored as an array of pairs"
    },
    "correct_answer": "B",
    "explanation": "An adjacency matrix requires O(V²) space, which would be 100 million entries for 10,000 vertices—far larger than needed. An adjacency list stores only the edges, using O(V + E) space (≈30,000 entries here), making it far more memory‑efficient for sparse graphs.",
    "difficulty": "Medium"
  },
  {
    "question": "Which property distinguishes a binary search tree (BST) from a generic binary tree?",
    "options": {
      "A": "Each node has at most two children",
      "B": "All leaf nodes are at the same depth",
      "C": "For any node, all keys in its left subtree are smaller and all keys in its right subtree are larger",
      "D": "The tree is always perfectly balanced"
    },
    "correct_answer": "C",
    "explanation": "A BST enforces an ordering invariant: every node's left subtree contains only keys less than the node’s key, and the right subtree contains only keys greater. This property enables logarithmic‑time search, insertion, and deletion on average. The other options describe generic binary trees or specific balanced variants, not the BST definition.",
    "difficulty": "Medium"
  },
  {
    "question": "When implementing a priority queue, which data structure provides the most efficient `extract‑max` (or `extract‑min`) operation while still supporting `insert` in logarithmic time?",
    "options": {
      "A": "Unsorted array",
      "B": "Sorted linked list",
      "C": "Binary heap",
      "D": "Binary search tree"
    },
    "correct_answer": "C",
    "explanation": "A binary heap maintains the heap property, allowing both insertion and removal of the maximum (or minimum) element in O(log n) time. An unsorted array would require O(n) for extraction, a sorted linked list O(1) for extraction but O(n) for insertion, and a BST can degrade to O(n) if unbalanced.",
    "difficulty": "Medium"
  }
]
